-- 多平台发布 v3: article_template 表
-- 模板 = 完整成文内容（非占位符骨架）
-- Target: YOUR_MYSQL_HOST:3306/ry-cloud2

USE `ry-cloud2`;

CREATE TABLE IF NOT EXISTS article_template (
  id              BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '模板ID',
  name            VARCHAR(200) NOT NULL COMMENT '模板名称',
  category        VARCHAR(50)  DEFAULT NULL COMMENT '模板分类',
  platform        VARCHAR(50)  NOT NULL COMMENT '默认目标平台编码',
  style_preset    VARCHAR(100) DEFAULT NULL COMMENT '默认样式预设名称',
  snapshot_json   LONGTEXT     NOT NULL COMMENT 'ProseMirror JSON 内容快照',
  thumbnail_url   VARCHAR(500) DEFAULT NULL COMMENT '缩略图',
  description     VARCHAR(500) DEFAULT NULL COMMENT '模板说明',
  sort_order      INT          DEFAULT 0 COMMENT '排序号',
  is_default      CHAR(1)      DEFAULT '0' COMMENT '是否默认模板：0否 1是',

  create_by       VARCHAR(64)  DEFAULT '' COMMENT '创建人',
  create_time     DATETIME     DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_by       VARCHAR(64)  DEFAULT '' COMMENT '更新人',
  update_time     DATETIME     DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  remark          VARCHAR(500) DEFAULT NULL COMMENT '备注',
  del_flag        CHAR(1)      DEFAULT '0' COMMENT '删除标志',

  KEY idx_category (category),
  KEY idx_platform (platform),
  KEY idx_sort (sort_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='文章模板';

-- 插入默认模板（完整成文，非占位符骨架）
INSERT INTO article_template (name, category, platform, style_preset, snapshot_json, description, sort_order, is_default, create_by) VALUES
('格物微信蓝', 'WECHAT', 'WECHAT_OFFICIAL_ACCOUNT', NULL,
'{"type":"doc","content":[{"type":"image","attrs":{"src":"https://picsum.photos/800/400","alt":"封面图"}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"写在前面"}]},{"type":"paragraph","content":[{"type":"text","text":"卫星遥感技术正在重塑全球农业监测体系。借助多光谱影像与AI识别算法，传统依赖人工踏勘的种植面积统计方式，正被"},{"type":"text","marks":[{"type":"bold"}],"text":"高频次、全覆盖、可追溯"},{"type":"text","text":"的卫星监测模式所替代。本文以SpaceMV平台2025年第四季度数据为基础，梳理全球主要产粮区的种植结构变化趋势。"}]},{"type":"paragraph","content":[{"type":"text","text":"2025"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"全球种植地图"}]},{"type":"paragraph","content":[]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"01"},{"type":"text","text":" 巴西大豆：创纪录的扩种周期"}]},{"type":"paragraph","content":[{"type":"text","text":"巴西2025/2026年度大豆种植面积预计达到"},{"type":"text","marks":[{"type":"bold"}],"text":"4,730万公顷"},{"type":"text","text":"，同比增长5.2%。卫星影像显示，马托格罗索州和戈亚斯州的"},{"type":"text","marks":[{"type":"underline"}],"text":"新增开垦面积"},{"type":"text","text":"较上年增加18%，部分区域由牧草地改种大豆。"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"种植面积："},{"type":"text","text":"4,730万公顷（+5.2%）"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"预估产量："},{"type":"text","text":"1.72亿吨"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"主产州："},{"type":"text","text":"马托格罗索（29%）、戈亚斯（12%）、南马托格罗索（10%）"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"监测周期："},{"type":"text","text":"2025年9月至2026年3月（生长季）"}]},{"type":"image","attrs":{"src":"https://picsum.photos/600/350","alt":"巴西大豆种植卫星影像"}},{"type":"paragraph","content":[{"type":"text","text":"巴西马托格罗索州大豆种植区卫星影像，影像时间：2025年12月（来源：SpaceMV卫星影像库）"}]},{"type":"paragraph","content":[]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"02"},{"type":"text","text":" 东南亚水稻：季风影响下的产量波动"}]},{"type":"paragraph","content":[{"type":"text","text":"2025年厄尔尼诺现象消退后，东南亚地区降水回归正常水平。泰国、越南的水稻种植面积恢复性增长，但"},{"type":"text","marks":[{"type":"italic"}],"text":"湄公河三角洲"},{"type":"text","text":"部分地区因海水倒灌，减产约8%。"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"泰国："},{"type":"text","text":"种植面积1,120万公顷，产量3,350万吨"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"越南："},{"type":"text","text":"种植面积750万公顷，产量2,840万吨"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"缅甸："},{"type":"text","text":"种植面积680万公顷，产量2,100万吨"}]}]}]},{"type":"image","attrs":{"src":"https://picsum.photos/600/350","alt":"湄公河三角洲水稻种植影像"}},{"type":"paragraph","content":[{"type":"text","text":"湄公河三角洲水稻种植区NDVI时序监测图（来源：SpaceMV）"}]},{"type":"paragraph","content":[]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"03"},{"type":"text","text":" 中国玉米：政策驱动下的结构调整"}]},{"type":"paragraph","content":[{"type":"text","text":"中国2025年玉米种植面积约"},{"type":"text","marks":[{"type":"bold"}],"text":"4,420万公顷"},{"type":"text","text":"，与上年基本持平。东北产区"},{"type":"text","marks":[{"type":"underline"}],"text":"大豆玉米轮作"},{"type":"text","text":"补贴政策持续推进，黑龙江省玉米种植面积微降1.2%，大豆面积相应增加。"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"黑龙江："},{"type":"text","text":"玉米980万公顷，大豆740万公顷"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"吉林："},{"type":"text","text":"玉米560万公顷"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"内蒙古："},{"type":"text","text":"玉米480万公顷"}]}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":""大豆玉米轮作补贴政策实施第三年，东北种植结构已发生显著变化。卫星数据清晰捕捉到了轮作区域的边界变化。""}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"—— SpaceMV农业分析师 王明远"}]}]},{"type":"paragraph","content":[]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"结语"}]},{"type":"paragraph","content":[{"type":"text","text":"卫星遥感数据正在成为全球农业决策的核心支撑。从巴西大豆的扩种到东南亚水稻的波动，再到中国玉米的结构调整，SpaceMV平台通过"},{"type":"text","marks":[{"type":"bold"}],"text":"高频卫星监测+AI作物识别"},{"type":"text","text":"技术，为用户提供及时、准确的种植结构变化数据。访问"},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://spacemv.com"}}],"text":"SpaceMV官方网站"},{"type":"text","text":"获取完整数据报告。"}]},{"type":"paragraph","content":[]},{"type":"paragraph","content":[{"type":"text","text":"编辑：张明远"}]},{"type":"paragraph","content":[{"type":"text","text":"审核：李思颖"}]},{"type":"paragraph","content":[]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"往期回顾"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://spacemv.com/reports/global-wheat-2025"}}],"text":"【全球小麦】2025年全球小麦主产区产量预测专题报告"}]},{"type":"paragraph","content":[]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"【特别声明】"}]},{"type":"paragraph","content":[{"type":"text","text":"1. 本文版权为SpaceMV所有，仅供您参考之用，不构成任何投资决策建议。如需购买完整数据或定制分析报告，请联系产品经理：李女士 lx@spacemv.com"}]},{"type":"paragraph","content":[{"type":"text","text":"2. 本报告数据来源于SpaceMV卫星遥感监测平台，已尽可能确保数据准确性，但不构成绝对保证。卫星影像受天气条件影响可能存在局部缺失。"}]},{"type":"paragraph","content":[]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"END"}]},{"type":"paragraph","content":[]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"作者简介"}]},{"type":"paragraph","content":[{"type":"text","text":"SpaceMV格物，您的全球种植资产向量地图。用卫星视角，洞察每一寸土地的变化。"}]},{"type":"image","attrs":{"src":"https://picsum.photos/200/200","alt":"SpaceMV二维码"}]}]}',
